def L(id, gradeId, chapter, category, title, minutes, order, theory, example, questions,
      plan=None, attention=None, worksheet=None, assessment=None, solutions=None, recap=None):
    d = {
        "id": id,
        "gradeId": gradeId,
        "chapter": chapter,
        "category": category,
        "title": title,
        "minutes": minutes,
        "order": order,
        "theory": theory,
        "example": example,
        "questions": questions,
    }
    if plan is not None:
        d["plan"] = plan
    if attention is not None:
        d["attention"] = attention
    if worksheet is not None:
        d["worksheet"] = worksheet
    if assessment is not None:
        d["assessment"] = assessment
    if solutions is not None:
        d["solutions"] = solutions
    if recap is not None:
        d["recap"] = recap
    return d


def Q(prompt, options, correct, explanation):
    return {"prompt": prompt, "options": options, "correct": correct, "explanation": explanation}


